source("R/config.R")
source("R/helpers_smcca.R")
library(PMA); library(dplyr)
dat <- read.csv(AVERAGE_INPUT,check.names=FALSE); expected_ncol <- N_PM+N_BEHAVIOR+N_BRAIN; stopifnot(ncol(dat)>=expected_ncol); xs <- make_xlist(scale(dat[,seq_len(expected_ncol)]),N_PM,N_BEHAVIOR,N_BRAIN)
tuning <- MultiCCA.permute(xs,type=c("standard","standard","standard"),nperms=N_PERM); fit <- fit_smcca(xs,tuning$bestpenalties,tuning$ws.init,N_COMPONENTS); v <- get_variates(xs,fit)
pm <- calc_loadings(xs[[1]],v$Pollution); beh <- calc_loadings(xs[[2]],v$Behavior); brain <- calc_loadings(xs[[3]],v$Brain)
colnames(pm)<-colnames(beh)<-colnames(brain)<-paste0("M",seq_len(N_COMPONENTS)); rownames(pm)<-PM_NAMES; rownames(beh)<-BEHAVIOR_NAMES; rownames(brain)<-paste0("Brain_",seq_len(N_BRAIN))
top20 <- bind_rows(lapply(seq_len(N_COMPONENTS),function(k){x<-top_brain_loadings(brain[,k],10);x$Mode<-paste0("M",k);x}))
cv <- run_repeated_cv(xs,tuning$bestpenalties,tuning$ws.init,N_COMPONENTS,N_CV_REPEATS,N_CV_FOLDS,SEED)
write.csv(pm,file.path(RESULT_DIR,"average_pollution_loadings.csv")); write.csv(beh,file.path(RESULT_DIR,"average_behavior_loadings.csv")); write.csv(brain,file.path(RESULT_DIR,"average_brain_loadings_all268.csv")); write.csv(top20,file.path(RESULT_DIR,"average_brain_loadings_top10_pos_neg.csv"),row.names=FALSE); write.csv(cv$summary,file.path(RESULT_DIR,"average_repeated_cv_summary.csv"),row.names=FALSE); saveRDS(list(tuning=tuning,fit=fit,variates=v,cv=cv),file.path(RESULT_DIR,"average_controllability_analysis.rds"))
